+/* 대표 상품 정보를 펼치는 층이다. 카드 안에서 한 단 아래로 내려간다. */
+.item [data-slot='profile'] {
+  margin: 0 16px;
+  padding-bottom: 14px;
+  border-top: 1px dashed var(--thorp-line);
+}
+
+.item [data-slot='profile-toggle'] {
+  display: inline-flex;
+  align-items: center;
+  gap: 6px;
+  margin-top: 10px;
+  padding: 5px 0;
+  border: 0;
+  background: none;
+  color: var(--thorp-copy);
+  font: inherit;
+  font-size: 0.8rem;
+  text-decoration: underline;
+  text-decoration-color: var(--thorp-line-strong);
+  text-underline-offset: 4px;
+  cursor: pointer;
+}
+
+.item [data-slot='profile-toggle']:hover {
+  color: var(--thorp-foreground);
+  text-decoration-color: currentColor;
+}
+
+/* 펼쳤는지를 글자 말고도 드러낸다. 삼각형이 돌아가는 방향이 곧 상태다. */
+.item [data-slot='profile-toggle']::before {
+  content: '';
+  width: 0;
+  height: 0;
+  border-top: 4px solid transparent;
+  border-bottom: 4px solid transparent;
+  border-left: 5px solid currentColor;
+  transition: transform 0.15s ease;
+}
+
+.item [data-slot='profile-toggle'][aria-expanded='true']::before {
+  transform: rotate(90deg);
+}
+
+.item [data-slot='profile-panel'] {
+  padding: 12px 0 2px;
+}
+
+.item [data-slot='profile-loading'] {
+  margin: 0;
+  color: var(--thorp-copy);
+  font-size: 0.84rem;
+  line-height: 1.7;
+}
+
+/*
+  이 패널에서 가장 먼저 읽혀야 하는 것이 구성이다. 상위 종목이 전체에서 차지하는 몫을 한 줄로
+  이어 붙여, 이름과 숫자를 읽기 전에 크기가 먼저 보이게 한다.
+*/
+.item [data-slot='composition-bar'] {
+  display: flex;
+  width: 100%;
+  height: 10px;
+  margin: 12px 0 10px;
+  overflow: hidden;
+  border-radius: 3px;
+  background: var(--thorp-surface-muted);
+}
+
+.item [data-slot='composition-segment'] {
+  flex: none;
+  border-right: 1px solid var(--thorp-surface);
+  background: var(--thorp-accent);
+}
+
+/* 뒤로 갈수록 옅어져 순서가 색으로도 읽힌다. */
+.item [data-slot='composition-segment']:nth-child(2) {
+  background: color-mix(in oklch, var(--thorp-accent), var(--thorp-surface) 28%);
+}
+
+.item [data-slot='composition-segment']:nth-child(3) {
+  background: color-mix(in oklch, var(--thorp-accent), var(--thorp-surface) 48%);
+}
+
+.item [data-slot='composition-segment']:nth-child(n + 4) {
+  background: color-mix(in oklch, var(--thorp-accent), var(--thorp-surface) 64%);
+}
+
+/* '그 외'는 상위 종목과 성격이 달라 강조 색을 쓰지 않는다. */
+.item [data-slot='composition-segment'][data-rest='true'] {
+  background: var(--thorp-line-strong);
+}
+
+.item [data-slot='holdings'] {
+  display: grid;
+  gap: 2px;
+  margin: 0 0 12px;
+  padding: 0;
+  list-style: none;
+}
+
+/*
+  이름과 비중 사이를 점선으로 이어 눈이 줄을 건너뛰지 않게 한다. 숫자는 등폭 자리를 잡아
+  자릿수가 달라도 소수점이 한 줄로 선다.
+*/
+.item [data-slot='holding'] {
+  display: grid;
+  grid-template-columns: auto 1fr auto;
+  align-items: baseline;
+  gap: 8px;
+  font-size: 0.82rem;
+}
+
+.item [data-slot='holding']::after {
+  content: '';
+  grid-column: 2;
+  border-bottom: 1px dotted var(--thorp-line);
+  transform: translateY(-3px);
+}
+
+.item [data-slot='holding'][data-rest='true'] {
+  color: var(--thorp-muted);
+}
+
+.item [data-slot='holding-name'] {
+  grid-column: 1;
+  overflow-wrap: anywhere;
+}
+
+.item [data-slot='holding-weight'] {
+  grid-column: 3;
+  font-variant-numeric: tabular-nums;
+}
+
+/* 결과의 뜻을 바꾸는 사실이라 상세 안에 접어 두지 않고 구성 바로 아래에 둔다. */
+.item [data-slot='composition-caveat'] {
+  margin: 0 0 12px;
+  padding-left: 10px;
+  border-left: 2px solid var(--thorp-warning);
+  color: var(--thorp-copy);
+  font-size: 0.78rem;
+  line-height: 1.6;
+}
+
+.item [data-slot='profile-facts'] {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 6px 28px;
+  margin: 0 0 12px;
+}
+
+.item [data-slot='profile-facts'] dt {
+  color: var(--thorp-muted);
+  font-size: 0.72rem;
+}
+
+.item [data-slot='profile-facts'] dd {
+  margin: 2px 0 0;
+  font-size: 0.86rem;
+  font-variant-numeric: tabular-nums;
+}
+
+.item [data-slot='profile-methodology'],
+.item [data-slot='profile-survivorship'],
+.item [data-slot='profile-sample'] {
+  margin: 0 0 8px;
+  color: var(--thorp-copy);
+  font-size: 0.78rem;
+  line-height: 1.7;
+}
+
+.item [data-slot='profile-sample'] {
+  padding: 8px 12px;
+  border: 1px dashed var(--thorp-line);
+  border-radius: 8px;
+}
+
+.item [data-slot='profile-source'] {
+  margin: 0;
+  color: var(--thorp-muted);
+  font-size: 0.72rem;
+}
+
+/* 패널 안의 '아직 줄 것이 없다' 표시는 카드 안이라 목록 화면의 것보다 여백을 줄인다. */
+.item [data-slot='profile-panel'] > div:not([data-slot='profile-body']) {
+  display: flex;
+  flex-direction: column;
+  align-items: flex-start;
+  gap: 10px;
+  padding: 14px;
+  border: 1px solid var(--thorp-line);
+  border-radius: 10px;
+}
+
+.item [data-slot='profile-panel'] > div:not([data-slot='profile-body']) p {
+  margin: 0;
+  color: var(--thorp-copy);
+  font-size: 0.82rem;
+  line-height: 1.6;
+}
+
+.item [data-slot='profile-panel'] > div:not([data-slot='profile-body']) button {
+  padding: 6px 14px;
+  border: 1px solid var(--thorp-line);
+  border-radius: 999px;
+  background: transparent;
+  color: inherit;
+  font: inherit;
+  font-size: 0.8rem;
+  cursor: pointer;
+}
+
+.item [data-slot='profile-panel'] > div:not([data-slot='profile-body']) button:hover {
+  border-color: currentColor;
+}
+
 /* 합계와 남은 비중이 놓이는 자리다. 별도 알림 영역으로 빼지 않는다. */
